#!/usr/bin/env node
/**
 * Wrap print-assets/nbd-logo-print.png into docs/pro/js/nbd-logo-asset.js
 * as a data URI.
 *
 * The generator embeds the logo as a data URI rather than linking it,
 * because the Universal Doc Viewer renders documents in a srcdoc iframe
 * whose null origin plus the CSP object-src rule make a linked image
 * unreliable. A data URI always resolves.
 *
 * This file used to be regenerated by an inline snippet nobody kept: its
 * own header read "To regenerate:  or just re-run the inline snippet in
 * this file's history" -- the command had been lost, and the source-of-
 * truth line described a 1536x1024 JPEG while the path it named held a
 * 240x160 file. Hence a real script, with zero dependencies so it runs
 * anywhere node does.
 *
 * Usage:  node scripts/build-logo-asset.js
 *         node scripts/build-logo-asset.js --check   (exit 1 if stale)
 *
 * To change the logo itself, replace print-assets/nbd-logo-master.png and
 * run scripts/crop-logo-master.py first.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.dirname(__dirname);
const SRC = path.join(ROOT, 'print-assets', 'nbd-logo-print.png');
const OUT = path.join(ROOT, 'docs', 'pro', 'js', 'nbd-logo-asset.js');
const CHECK = process.argv.includes('--check');

const png = fs.readFileSync(SRC);
if (png.slice(0, 8).toString('hex') !== '89504e470d0a1a0a') {
  console.error('Not a PNG: ' + SRC);
  process.exit(1);
}
const width = png.readUInt32BE(16);
const height = png.readUInt32BE(20);
const kb = Math.round(png.length / 1024);

const module_ = [
  '/* Inline NBD logo as a data URI. Bypasses the CSP object-src rule and the',
  '   null-origin srcdoc iframe the Universal Doc Viewer renders documents in,',
  '   either of which can stop a linked image from loading.',
  '',
  '   GENERATED FILE — do not hand-edit.',
  '   Source of truth: print-assets/nbd-logo-master.png (the studio master).',
  '   Print render:    print-assets/nbd-logo-print.png (' + width + 'x' + height + ' PNG, ~' + kb + ' KB),',
  '                    cropped to the artwork by scripts/crop-logo-master.py.',
  '   Regenerate:      node scripts/build-logo-asset.js */',
  "window.NBD_LOGO_DATA_URI = 'data:image/png;base64," + png.toString('base64') + "';",
  '',
].join('\n');

if (CHECK) {
  const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (current !== module_) {
    console.error('nbd-logo-asset.js is stale — run: node scripts/build-logo-asset.js');
    process.exit(1);
  }
  console.log('nbd-logo-asset.js is up to date (' + width + 'x' + height + ', ~' + kb + ' KB).');
  process.exit(0);
}

fs.writeFileSync(OUT, module_);
console.log('Wrote docs/pro/js/nbd-logo-asset.js');
console.log('  ' + width + 'x' + height + ' PNG, ' + png.length + ' bytes -> ' +
            Math.round(module_.length / 1024) + ' KB module');
